import type { JSX } from 'react'
import './StatusList.css'
import type { Status, StatusItem } from '../../types'

export const STATUS_LABELS: Record<Status, string> = {
  'todo': 'To Do',
  'in-progress': 'In Progress',
  'done': 'Done',
  'blocked': 'Blocked',
}

export const SKELETON_COUNT = 6

export function statusColor(status: Status): string {
  switch (status) {
    case 'todo': return 'status-list-item--todo'
    case 'in-progress': return 'status-list-item--in-progress'
    case 'done': return 'status-list-item--done'
    case 'blocked': return 'status-list-item--blocked'
  }
}

function groupByStatus(items: StatusItem[]): Map<Status, StatusItem[]> {
  const order: Status[] = ['todo', 'in-progress', 'done', 'blocked']
  const map = new Map<Status, StatusItem[]>()
  for (const status of order) {
    map.set(status, [])
  }
  for (const item of items) {
    const group = map.get(item.status)
    if (group) {
      group.push(item)
    }
  }
  return map
}

interface StatusListProps {
  items: StatusItem[] | null
}

export function StatusList({ items }: StatusListProps): JSX.Element {
  if (items === null) {
    return (
      <ul className="status-list" role="list" aria-label="Status list loading">
        {Array.from({ length: SKELETON_COUNT }, (_, i) => (
          <li key={i} className="status-list-item">
            <div className="status-list-skeleton" />
          </li>
        ))}
      </ul>
    )
  }

  const groups = groupByStatus(items)
  const statusOrder: Status[] = ['todo', 'in-progress', 'done', 'blocked']

  return (
    <ul className="status-list" role="list" aria-label="Status list">
      {statusOrder.map((status) => {
        const group = groups.get(status) ?? []
        if (group.length === 0) return null
        return (
          <li key={status}>
            <h3 className="status-group-heading">{STATUS_LABELS[status]}</h3>
            <ul role="list">
              {group.map((item) => (
                <li key={item.id} className={`status-list-item ${statusColor(item.status)}`}>
                  {item.title}
                </li>
              ))}
            </ul>
          </li>
        )
      })}
    </ul>
  )
}

