import './ChipFilter.css'

type FilterChip = 'All' | 'Active' | 'Archived' | 'Starred'

const CHIPS: FilterChip[] = ['All', 'Active', 'Archived', 'Starred']

// Owns only visual pressed state; grid filtering is not wired.
export function ChipFilter(): JSX.Element {
  const [pressed, setPressed] = useState<FilterChip>('All')

  return (
    <div className="chip-bar" role="toolbar" aria-label="Filter chips">
      {CHIPS.map((chip) => (
        <button
          key={chip}
          className="chip"
          aria-pressed={pressed === chip}
          onClick={() => setPressed(chip)}
        >
          {chip}
        </button>
      ))}
    </div>
  )
}

