import { useEffect, useState } from 'react'
import type { JSX } from 'react'
import './TaskBoard.css'
import { getTasks } from '../../api'
import type { StatusItem } from '../../types'

const SKELETON_COUNT = 5

// null = loading; array = loaded
export function TaskBoard(): JSX.Element {
  const [tasks, setTasks] = useState<StatusItem[] | null>(null)

  useEffect(() => {
    getTasks()
      .then((data) => setTasks(data))
      .catch(() => setTasks([]))
  }, [])

  function renderBody(): JSX.Element {
    if (tasks === null) {
      return (
        <ul className="task-board-list" role="list" aria-label="Tasks loading">
          {Array.from({ length: SKELETON_COUNT }, (_, i) => (
            <li key={i} className="task-board-item">
              <div className="task-board-skeleton" />
            </li>
          ))}
        </ul>
      )
    }

    if (tasks.length === 0) {
      return (
        <ul className="task-board-list" role="list" aria-label="Tasks">
          <li className="task-board-empty">No tasks yet</li>
        </ul>
      )
    }

    return (
      <ul className="task-board-list" role="list" aria-label="Tasks">
        {tasks.map((task) => (
          <li key={task.id} className="task-board-item">
            {task.title}
          </li>
        ))}
      </ul>
    )
  }

  const count = tasks === null ? 0 : tasks.length

  return (
    <div className="task-board">
      <div className="task-board-header">
        <h2 className="task-board-heading">Tasks</h2>
        <span className="task-board-badge" aria-label={`${count} tasks`}>{count}</span>
      </div>
      <div className="task-board-filter-bar" />
      {renderBody()}
    </div>
  )
}

