import './PriceDisplay.css';

interface PriceDisplayProps {
  price: number;
  originalPrice?: number;
  currency?: string;
}

function formatPrice(amount: number, currency: string): string {
  // Math.ceil: always round up to avoid under-charging the customer
  return `${currency}${Math.ceil(amount).toFixed(2)}`;
}

export function PriceDisplay({ price, originalPrice, currency = '$' }: PriceDisplayProps): JSX.Element {
  const hasDiscount = originalPrice !== undefined && originalPrice > price;

  return (
    <span className="price-display">
      <span className="price-display-current">{formatPrice(price, currency)}</span>
      {hasDiscount && (
        <span className="price-display-original">{formatPrice(originalPrice, currency)}</span>
      )}
    </span>
  );
}

