import './DataTable.css'
import type { Row } from '../../types'

interface DataTableProps {
  rows: Row[]
  loading: boolean
}

const SKELETON_ROW_COUNT = 5
const SKELETON_COL_COUNT = 3

export function DataTable({ rows, loading }: DataTableProps): JSX.Element {
  const columns = rows.length > 0 ? Object.keys(rows[0]) : []
  const colCount = columns.length > 0 ? columns.length : SKELETON_COL_COUNT

  return (
    <table role="table" className="data-table">
      <thead>
        <tr>
          {loading && columns.length === 0
            ? Array.from({ length: colCount }, (_, i) => (
                <th key={i} scope="col">
                  <span className="data-table-skeleton-cell" />
                </th>
              ))
            : columns.map((col) => (
                <th key={col} scope="col">{col}</th>
              ))
          }
        </tr>
      </thead>
      <tbody>
        {loading
          ? Array.from({ length: SKELETON_ROW_COUNT }, (_, rowIdx) => (
              <tr key={rowIdx}>
                {Array.from({ length: colCount }, (_, colIdx) => (
                  <td key={colIdx}>
                    <span className="data-table-skeleton-cell" />
                  </td>
                ))}
              </tr>
            ))
          : rows.map((row, rowIdx) => (
              <tr key={rowIdx}>
                {columns.map((col) => (
                  <td key={col}>{String(row[col] ?? '')}</td>
                ))}
              </tr>
            ))
        }
      </tbody>
    </table>
  )
}

